(function() {
  var TAG_INDICATOR_CLASS = 'cs-auto-tag-suggestion';

  var keywordMap = {
    'bug': 'bug-report',
    'error': 'bug-report',
    'fix': 'bug-fix',
    'feature': 'feature-request',
    'enhancement': 'feature-request',
    'urgent': 'priority-high',
    'critical': 'priority-high',
    'blocker': 'priority-high',
    'minor': 'priority-low',
    'todo': 'task',
    'task': 'task',
    'review': 'needs-review',
    'feedback': 'needs-review',
    'docs': 'documentation',
    'documentation': 'documentation',
    'api': 'api-related',
    'endpoint': 'api-related',
    'test': 'testing',
    'spec': 'testing',
    'design': 'design',
    'ui': 'design',
    'ux': 'design',
    'performance': 'performance',
    'slow': 'performance',
    'optimize': 'performance',
    'security': 'security',
    'auth': 'security',
    'deploy': 'devops',
    'ci': 'devops',
    'pipeline': 'devops'
  };

  function extractSuggestedTags(text) {
    if (!text || typeof text !== 'string') return [];
    var lower = text.toLowerCase();
    var words = lower.split(/[\s,.;:!?()\[\]{}"']+/);
    var tagSet = {};
    for (var i = 0; i < words.length; i++) {
      var word = words[i].trim();
      if (keywordMap[word]) {
        tagSet[keywordMap[word]] = true;
      }
    }
    return Object.keys(tagSet).sort();
  }

  function removeSuggestions() {
    var elems = document.querySelectorAll('.' + TAG_INDICATOR_CLASS);
    for (var i = 0; i < elems.length; i++) {
      elems[i].parentNode.removeChild(elems[i]);
    }
  }

  CardSpoke_MODS.register({
    name: 'Auto Tagger',
    hooks: {
      onAppInit: function() {
        console.log('[Auto Tagger] Mod initialized with', Object.keys(keywordMap).length, 'keyword rules');
      },
      onCardSave: function(cardData) {
        if (!cardData || !cardData.body) return cardData;
        var suggested = extractSuggestedTags(cardData.body);
        if (suggested.length > 0) {
          var existing = cardData.tags || [];
          var newTags = [];
          for (var i = 0; i < suggested.length; i++) {
            if (existing.indexOf(suggested[i]) === -1) {
              newTags.push(suggested[i]);
            }
          }
          if (newTags.length > 0) {
            cardData.tags = existing.concat(newTags);
            console.log('[Auto Tagger] Suggested tags:', newTags.join(', '));
          }
        }
        return cardData;
      },
      onDisable: function() {
        removeSuggestions();
        console.log('[Auto Tagger] Mod disabled');
      }
    }
  });
})()
